}

export interface PairedAblationQuery {
  id: string;
  expected?: unknown;
  answer?: unknown;
  safety?: { forbid?: boolean; deny?: boolean };
}

export interface PairedAblationCase {
  id: string;
  items: Array<PairedAblationItem | string>;
  queries: PairedAblationQuery[];
}

export interface PairedAblationFixture {
  schemaVersion?: number;
  seed?: number;
  repetitions?: number;
  cases: PairedAblationCase[];
  preregistration?: Record<string, unknown>;
}

export interface RuntimeMemoryStoreFactoryOptions {
  condition: 'baseline' | 'treatment';
  seed: number;
  caseId: string;
  repetition: number;
  phase4Policy: 'fifo' | 'type-aware';
  isolated: true;
}

export interface RuntimeMemoryStoreLike {
  insert?(id: string, value: unknown, metadata?: Record<string, unknown>): unknown;
  set?(id: string, value: unknown, metadata?: Record<string, unknown>): unknown;
  put?(id: string, value: unknown, metadata?: Record<string, unknown>): unknown;
  get?(id: string): unknown;
  retrieve?(id: string): unknown;
  retainedIds?(): unknown;
  keys?(): unknown;
  evictedIds?(): unknown;
  evictions?(): unknown;
  clear?(): unknown;
}

export type RuntimeMemoryStoreFactory = (
  options: RuntimeMemoryStoreFactoryOptions,
) => RuntimeMemoryStoreLike | Promise<RuntimeMemoryStoreLike>;

export interface PairedAblationObservation {
  caseId: string;
  condition: 'baseline' | 'treatment';
  repetition: number;
  seed: number;
  success: boolean;
  pass: boolean;
  latencyMs: number;
  tokensProxy: number;
  falseIntercepts: number;
  safetyViolations: number;
  wrongAnswers: number;
  retained: string[];
  evicted: string[];
  queriedIds: string[];
  expectedQueryCount: number;
}

export interface DistributionSummary {
  count: number;
  p50: number | null;
  p95: number | null;
}

export interface ArmSummary {
  observations: number;
  cases: number;
  success: number;
  passAtK: number;
  latencyMs: DistributionSummary;
  tokensProxy: DistributionSummary;
  falseIntercepts: number;
  safetyViolations: number;
}

export interface EffectSummary {
  point: number | null;
  meanDifference: number | null;
  low: number | null;
  high: number | null;
  standardError: number | null;
  relative: number | null;
  method: 'paired-percentile-bootstrap';
  bootstrapSamples: number;
  note: string;
}

export interface PairedAblationResult {
  schemaVersion: 1;
  experiment: string;
  preregistration: Record<string, unknown> | null;
  seed: number;
  repetitions: number;
  cases: number;
  effectVerified: boolean;
  decisionDifferences: Array<{ caseId: string; retainedChanged: boolean; evictedChanged: boolean }>;
  baseline: ArmSummary;
  treatment: ArmSummary;
  effects: {
    pairs: number;
    success: EffectSummary;
    passAtK: { baseline: number; treatment: number };
    latencyMs: EffectSummary;
    tokensProxy: EffectSummary;
    falseIntercepts: EffectSummary;
    safetyViolations: EffectSummary;
  };
  observations: { baseline: PairedAblationObservation[]; treatment: PairedAblationObservation[] };
}

export function passAtK(observations: PairedAblationObservation[], k?: number): number;\nexport function summarizeArm(observations: PairedAblationObservation[]): ArmSummary;
export function comparePaired(
  baseline: PairedAblationObservation[],
  treatment: PairedAblationObservation[],
  seed?: number,
): PairedAblationResult['effects'];
export function runPairedAblation(options: {
  fixture: PairedAblationFixture;
  createRuntimeMemoryStore: RuntimeMemoryStoreFactory;
  operations?: {
    insert?: RuntimeMemoryStoreLike['insert'];
    retrieve?: RuntimeMemoryStoreLike['get'];
    retained?: RuntimeMemoryStoreLike['retainedIds'];
    evicted?: RuntimeMemoryStoreLike['evictedIds'];
    clear?: RuntimeMemoryStoreLike['clear'];
  };
  repetitions?: number;
  seed?: number;
  requireEffectVerification?: boolean;
}): Promise<PairedAblationResult>;
export function loadFixture(filename: string): Promise<PairedAblationFixture>;
export function loadRuntimeMemoryStoreFactory(moduleFilename: string, exportName?: string): Promise<RuntimeMemoryStoreFactory>;
export const pairedAblationDefaults: Readonly<{
  repetitions: number;
  bootstrapSamples: number;
  confidence: number;
  seed: number;
}>;
