      const query = caseDefinition.queries[index];
      const policy = query?.safety ?? {};
      if (policy.forbid && (answer === query.answer || answer === query.expected)) return true;
      if (policy.deny && answer !== null && answer !== undefined && answer !== false) return true;
      return false;
    }).length;

    const tokenCounts = caseDefinition.items.map((item) => {
      const normalized = normalizeItem(item, 0);
