{"edits":[{"path":"scripts/lib/paired-ablation.mjs","content":"import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

/**
 * Paired, local-only ablation runner for E02.
 *
 * The runner deliberately owns no policy implementation.  A RuntimeMemoryStore
 * adapter supplies an isolated store and records retain/evict decisions.  The
 * treatment and baseline are the same real store with the caller's Phase-4
 * policy switch changed.  This makes the experiment reversible and ensures
 * that the two arms cannot silently use different implementations.
 */

const DEFAULTS = Object.freeze({
  repetitions: 3,
  bootstrapSamples: 10_000,
  confidence: 0.95,
  seed: 0x454f32,
});

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);
const mean = (values) => values.length === 0 ? null : values.reduce((a, b) => a + b, 0) / values.length;

function quantile(values, probability) {
  if (values.length === 0) return null;
  const ordered = [...values].sort((a, b) => a - b);
  const position = (ordered.length - 1) * probability;
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return ordered[lower];
  const fraction = position - lower;
  return ordered[lower] * (1 - fraction) + ordered[upper] * fraction;
}

function variance(values) {
  if (values.length < 2) return null;
  const average = mean(values);
  return values.reduce((sum, value) => sum + ((value - average) ** 2), 0) / (values.length - 1);
}

function standardError(values) {
  const value = variance(values);
  return value === null ? null : Math.sqrt(value / values.length);
}

function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function pairedBootstrap(differences, samples, seed) {
  if (differences.length === 0) return { point: null, low: null, high: null, method: 'paired-percentile-bootstrap' };
  const random = mulberry32(seed);
  const estimates = [];
  for (let sample = 0; sample < samples; sample += 1) {
    let total = 0;
    for (let index = 0; index < differences.length; index += 1) {
      total += differences[Math.floor(random() * differences.length)];
    }
    estimates.push(total / differences.length);
  }
  estimates.sort((a, b) => a - b);
  const alpha = (1 - DEFAULTS.confidence) / 2;
  return {
    point: mean(differences),
    low: quantile(estimates, alpha),
    high: quantile(estimates, 1 - alpha),
    method: 'paired-percentile-bootstrap',
    bootstrapSamples: samples,
  };
}

function pairedEffect(differences, seed) {
  const point = mean(differences);
  const error = standardError(differences);
  const bootstrap = pairedBootstrap(differences, DEFAULTS.bootstrapSamples, seed);
  return {
    ...bootstrap,
    meanDifference: point,
    standardError: error,
    relative: point === null || point === 0 ? null : point / Math.abs(point),
    note: 'treatment minus baseline; positive means treatment is larger',
  };
}

function describe(values) {
  const numeric = values.filter(isFiniteNumber);
  return {
    count: numeric.length,
    p50: quantile(numeric, 0.50),
    p95: quantile(numeric, 0.95),
  };
}

function normalizeItem(item, index) {
  if (typeof item === 'string') return { id: item, value: item, type: 'text' };
  if (!item || typeof item !== 'object') throw new TypeError(`fixture case item ${index} must be an object or string`);
  const id = item.id ?? item.key ?? item.name;
  if (typeof id !== 'string') throw new TypeError(`fixture case item ${index} requires a string id`);
  return {
    ...item,
    id,
    value: item.value ?? item.content ?? item.text ?? item,
    type: item.type ?? item.kind ?? 'text',
  };
}

function stableJson(value) {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function hashString(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function seedFor(baseSeed, caseId, condition, repetition) {
  return (baseSeed ^ hashString(`${caseId}|${condition}|${repetition}`)) >>> 0;
}

function assertNoUnsafeContent(caseDefinition) {
  const serialized = stableJson(caseDefinition);
  const forbidden = /(?:api[_-]?key|authorization|bearer\s+[a-z0-9._-]+|sk-[a-z0-9]{12,}|password\s*[:=])/i;
  if (forbidden.test(serialized)) throw new Error(`fixture case ${caseDefinition.id} appears to contain credentials`);
}

function createAdapter(options) {
  const factory = options.createRuntimeMemoryStore;
  if (typeof factory !== 'function') throw new TypeError('createRuntimeMemoryStore must be a function');

  return async function runArm({ condition, caseDefinition, repetition, seed }) {
    const store = await factory({
      condition,
      seed,
      caseId: caseDefinition.id,
      repetition,
      // The adapter must apply exactly one reversible Phase-4 switch.
      phase4Policy: condition === 'treatment' ? 'type-aware' : 'fifo',
      isolated: true,
    });
    if (!store || typeof store !== 'object') throw new TypeError('RuntimeMemoryStore factory did not return a store');

    const operations = options.operations ?? {};
    const insert = operations.insert ?? store.insert ?? store.set ?? store.put;
    const retrieve = operations.retrieve ?? store.get ?? store.retrieve;
    const retained = operations.retained ?? store.retainedIds ?? store.keys;
    const evicted = operations.evicted ?? store.evictedIds ?? store.evictions;
    const clear = operations.clear ?? store.clear;
    if (typeof insert !== 'function' || typeof retrieve !== 'function') {
      throw new TypeError('RuntimeMemoryStore adapter requires insert/set/put and get/retrieve functions');
    }

    const decisions = { retained: [], evicted: [] };
    const started = performance.now();
    for (const rawItem of caseDefinition.items) {
      const item = normalizeItem(rawItem, 0);
      await insert.call(store, item.id, item.value, { type: item.type, metadata: item.metadata });
    }
    const queryIds = caseDefinition.queries.map((query) => query.id);
    const answers = [];
    for (const queryId of queryIds) {
      const result = await retrieve.call(store, queryId);
      answers.push(result);
    }
    const elapsedMs = performance.now() - started;

    const readList = async (candidate) => {
      if (typeof candidate !== 'function') return [];
      const value = await candidate.call(store);
      return Array.isArray(value) ? value.map(String) : value instanceof Set ? [...value].map(String) : [];
    };
    decisions.retained = await readList(retained);
    decisions.evicted = await readList(evicted);
    if (typeof clear === 'function') await clear.call(store);

    const expected = new Set(queryIds);
    const falseIntercepts = answers.filter((answer) => answer === null || answer === undefined || answer === false).length;
    const wrongAnswers = answers.filter((answer, index) => {
      const query = caseDefinition.queries[index];
      if (query === null || query === undefined || query === false) return false;
      if (answer === null || answer === undefined || answer === false) return true;
      if (typeof answer === 'object' && 'hit' in answer) return !answer.hit;
      return stableJson(answer) !== stableJson(query.expected ?? query.answer);
    }).length;
    const safetyViolations = answers.filter((answer, index) => {
      const query = caseDefinition.queries[index];
      const policy = query?.safety ?? {};
      if (policy.forbid && (answer === query.answer || answer === query.expected)) return true;
      if (policy.deny && answer !== null && answer !== undefined && answer !== false) return true;
      return false;
    }).length;

    const tokenCounts = caseDefinition.items.map((item) => {
      const normalized = normalizeItem(item, 0);
      const text = typeof normalized.value === 'string' ? normalized.value : stableJson(normalized.value);
      return Math.max(1, Math.ceil(text.length / 4));
    });

    return {
      caseId: caseDefinition.id,
      condition,
      repetition,
      seed,
      success: wrongAnswers === 0 && safetyViolations === 0,
      pass: wrongAnswers === 0 && safetyViolations === 0,
      latencyMs: elapsedMs,
      tokensProxy: tokenCounts.reduce((sum, value) => sum + value, 0),
      falseIntercepts,
      safetyViolations,
      wrongAnswers,
      retained: decisions.retained,
      evicted: decisions.evicted,
      queriedIds: queryIds,
      expectedQueryCount: expected.size,
    };
  };
}

/**
 * E01-compatible pass^k calculation: an observation passes only when every
 * one of the k paired repetitions succeeds.  The returned value is a rate.
 * A case with zero repetitions is not silently promoted to success.
 */
export function passAtK(observations, k = observations.length) {
  if (!Number.isInteger(k) || k < 1) throw new RangeError('k must be a positive integer');
  const grouped = new Map();
  for (const observation of observations) {
    const values = grouped.get(observation.caseId) ?? [];
    values.push(Boolean(observation.pass));
    grouped.set(observation.caseId, values);
  }
  if (grouped.size === 0) return 0;
  let passingCases = 0;
  for (const values of grouped.values()) {
    const selected = values.slice(0, k);
    if (selected.length === k && selected.every(Boolean)) passingCases += 1;
  }
  return passingCases / grouped.size;
}

export function summarizeArm(observations) {
  const pass1 = observations.length === 0 ? 0 : observations.filter((item) => item.pass).length / observations.length;
  const perCase = new Map();
  for (const observation of observations) {
    const values = perCase.get(observation.caseId) ?? [];
    values.push(observation.pass);
    perCase.set(observation.caseId, values);
  }
  const passK = perCase.size === 0 ? 0 : [...perCase.values()].filter((values) => values.every(Boolean)).length / perCase.size;
  return {
    observations: observations.length,
    cases: perCase.size,
    success: pass1,
    passAtK: passK,
    latencyMs: describe(observations.map((item) => item.latencyMs)),
    tokensProxy: describe(observations.map((item) => item.tokensProxy)),
    falseIntercepts: observations.reduce((sum, item) => sum + item.falseIntercepts, 0),
    safetyViolations: observations.reduce((sum, item) => sum + item.safetyViolations, 0),
  };
}

export function comparePaired(baseline, treatment, seed = DEFAULTS.seed) {
  const baselineByKey = new Map(baseline.map((item) => [`${item.caseId}|${item.repetition}`, item]));
  const pairs = treatment.map((item) => {
    const control = baselineByKey.get(`${item.caseId}|${item.repetition}`);
    if (!control) throw new Error(`unpaired observation for ${item.caseId}/${item.repetition}`);
    return { baseline: control, treatment: item };
  });
  const difference = (field) => pairs.map(({ baseline: control, treatment: arm }) => arm[field] - control[field]);
  return {
    pairs: pairs.length,
    success: pairedEffect(difference('success'), seed ^ 0x11),
    passAtK: {
      baseline: passAtK(baseline),
      treatment: passAtK(treatment),
    },
    latencyMs: pairedEffect(difference('latencyMs'), seed ^ 0x22),
    tokensProxy: pairedEffect(difference('tokensProxy'), seed ^ 0x33),
    falseIntercepts: pairedEffect(difference('falseIntercepts'), seed ^ 0x44),
    safetyViolations: pairedEffect(difference('safetyViolations'), seed ^ 0x55),
  };
}

export async function runPairedAblation(options) {
  if (!options || typeof options !== 'object') throw new TypeError('options are required');
  const fixture = options.fixture;
  if (!fixture || !Array.isArray(fixture.cases)) throw new TypeError('fixture.cases must be an array');
  if (fixture.cases.length < 20) throw new Error('E02 requires at least 20 deterministic cases');
  const repetitions = options.repetitions ?? fixture.repetitions ?? DEFAULTS.repetitions;
  if (!Number.isInteger(repetitions) || repetitions < 1) throw new RangeError('repetitions must be a positive integer');
  const seed = options.seed ?? fixture.seed ?? DEFAULTS.seed;
  const runArm = createAdapter(options);
  const baseline = [];
  const treatment = [];

  for (const caseDefinition of fixture.cases) {
    if (!caseDefinition || typeof caseDefinition.id !== 'string') throw new TypeError('every fixture case requires an id');
    if (!Array.isArray(caseDefinition.items) || !Array.isArray(caseDefinition.queries)) throw new TypeError(`case ${caseDefinition.id} requires items and queries`);
    assertNoUnsafeContent(caseDefinition);
    for (let repetition = 0; repetition < repetitions; repetition += 1) {
      const baselineSeed = seedFor(seed, caseDefinition.id, 'baseline', repetition);
      const treatmentSeed = seedFor(seed, caseDefinition.id, 'treatment', repetition);
      baseline.push(await runArm({ condition: 'baseline', caseDefinition, repetition, seed: baselineSeed }));
      treatment.push(await runArm({ condition: 'treatment', caseDefinition, repetition, seed: treatmentSeed }));
    }
  }

  const decisionDifferences = baseline.map((control, index) => ({
    caseId: control.caseId,
    retainedChanged: stableJson(control.retained) !== stableJson(treatment[index].retained),
    evictedChanged: stableJson(control.evicted) !== stableJson(treatment[index].evicted),
  }));
  const effectVerified = decisionDifferences.some((item) => item.retainedChanged || item.evictedChanged);
  if (options.requireEffectVerification !== false && !effectVerified) {
    throw new Error('component effect was not observed: baseline and treatment retention/eviction sets are identical');
  }

  return {
    schemaVersion: 1,
    experiment: 'E02 Phase-4 type-aware eviction paired ablation',
    preregistration: fixture.preregistration ?? null,
    seed,
    repetitions,
    cases: fixture.cases.length,
    effectVerified,
    decisionDifferences,
    baseline: summarizeArm(baseline),
    treatment: summarizeArm(treatment),
    effects: comparePaired(baseline, treatment, seed),
    observations: { baseline, treatment },
  };
}

export async function loadFixture(filename) {
  return JSON.parse(await readFile(filename, 'utf8'));
}

export async function loadRuntimeMemoryStoreFactory(moduleFilename, exportName = 'createRuntimeMemoryStore') {
  const module = await import(pathToFileURL(path.resolve(moduleFilename)).href);
  const factory = module[exportName] ?? module.default?.[exportName] ?? module.default;
  if (typeof factory !== 'function') throw new TypeError(`${moduleFilename} does not export ${exportName}`);
  return factory;
}

export const pairedAblationDefaults = DEFAULTS;
