    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function pairedBootstrap(differences, samples, seed) {
  if (differences.length === 0) return { point: null, low: null, high: null, method: 'paired-percentile-bootstrap' };
  const random = mulberry32(seed);
  const estimates = [];
  for (let sample = 0; sample < samples; sample += 1) {
    let total = 0;
    for (let index = 0; index < differences.length; index += 1) {
      total += differences[Math.floor(random() * differences.length)];
    }
    estimates.push(total / differences.length);
  }
  estimates.sort((a, b) => a - b);
  const alpha = (1 - DEFAULTS.confidence) / 2;
  return {
    point: mean(differences),
    low: quantile(estimates, alpha),
    high: quantile(estimates, 1 - alpha),
    method: 'paired-percentile-bootstrap',
    bootstrapSamples: samples,
  };
}

function pairedEffect(differences, seed) {
  const point = mean(differences);
  const error = standardError(differences);
  const bootstrap = pairedBootstrap(differences, DEFAULTS.bootstrapSamples, seed);
  return {
    ...bootstrap,
    meanDifference: point,
    standardError: error,
    relative: point === null || point === 0 ? null : point / Math.abs(point),
    note: 'treatment minus baseline; positive means treatment is larger',
  };
